namespace GrowLog.Api.Data;

/// <summary>A permanent record of something that happened. Events are never changed or removed.</summary>
internal sealed class Event
{
    /// <summary>Generated by the client, so a resend from an offline queue is recognised.</summary>
    public required Guid Id { get; init; }

    public required EventType Type { get; init; }

    /// <summary>When the work happened, which can be well before it reached the server.</summary>
    public required DateTimeOffset OccurredAt
    {
        get;
        init => field = value.ToUniversalTime();
    }

    /// <summary>When the server stored the event. Set by the database.</summary>
    public DateTimeOffset RecordedAt { get; private set; }

    public required Guid RecordedBy { get; init; }

    /// <summary>The event this one reverses. Set only on <see cref="EventType.Corrected"/> events.</summary>
    public Guid? CorrectsEventId { get; init; }

    /// <summary>Details specific to the event type, as JSON. Must not contain personal data, which has to stay erasable.</summary>
    public string Payload { get; init; } = "{}";
}
